// ============================================
// VALIDATION INPUT - Syllabus Generator
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Specific webhook parameters ---
const topic = body.topic || ctx.topic || null;

if (!topic) {
  errors.push('topic requis');
}

// Parse options with defaults
const options = body.options || ctx.options || {};
const level = options.level || 'intermediaire';
const durationWeeks = options.duration_weeks || 8;
const hoursPerWeek = options.hours_per_week || 4;
const language = options.language || 'fr';
const format = options.format || 'hybride';
const additionalContext = body.context_text || ctx.context_text || '';

// Validate level enum
if (!['debutant', 'intermediaire', 'avance'].includes(level)) {
  errors.push('level doit etre debutant, intermediaire ou avance');
}

// Validate format enum
if (!['theorique', 'pratique', 'hybride'].includes(format)) {
  errors.push('format doit etre theorique, pratique ou hybride');
}

// --- API Keys passed from MCP Server ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';
const model = body.model || ctx.model || 'gpt-4o';

if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  topic: topic,
  level: level,
  duration_weeks: durationWeeks,
  hours_per_week: hoursPerWeek,
  language: language,
  format: format,
  context_text: additionalContext,
  openaiApiKey: openaiApiKey,
  model: model,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

